count("label", o=>1);
count("keys", o=>Object.keys(o).join(","));
count("hitIsTarget", o=>o.hitIsTarget);
count("pointInViewport", o=>o.pointInViewport);
count("target.tag", o=>o.target?.tag);
count("hit.tag", o=>o.hit?.tag);
count("hit null", o=>o.hit===null);
count("sticky", o=>o.stickyAncestor);
count("scrollLock", o=>o.scrollLock);
count("shadow", o=>[o.hitPathShadowRoots,o.hitPathIframes,o.openShadowRootsOnPage,o.iframesOnPage]);
count("ancestorState", o=>o.ancestorState?.map((a:any)=>[a.tag,a.inert,a.disabled,a.ariaDisabled,a.matchesDisabled].join("/")).join(" "));
count("chain pe", o=>o.chain?.map((c:any)=>c.tag+":"+c.pointerEvents+":"+c.visibility+":"+c.opacity+":"+c.position+":"+c.zIndex).join(" "));
count("attr keys", o=>Object.keys(o.target?.attributes??{}).join(","));
count("title", o=>o.title);
count("url", o=>String(o.finalUrl).replace(/[0-9a-f]{6,}/g,"X").slice(0,60));
count("target keys", o=>Object.keys(o.target??{}).join(","));
count("hit keys", o=>Object.keys(o.hit??{}).join(","));
count("box zero", o=>[o.target?.box?.width>0,o.target?.box?.height>0]);
EOF
